package com.ruoyi.web.controller.projectmanagement;
import com.ruoyi.common.annotation.Log; import com.ruoyi.common.core.controller.BaseController; import com.ruoyi.common.core.domain.AjaxResult; import com.ruoyi.common.core.page.TableDataInfo; import com.ruoyi.common.enums.BusinessType; import com.ruoyi.projectmanagement.execution.domain.LifecycleActionRequest; import com.ruoyi.projectmanagement.project.domain.ProjectInfo;import com.ruoyi.projectmanagement.project.domain.ProjectPreliminaryPlan;import com.ruoyi.projectmanagement.project.domain.InitiationReviewRequest; import com.ruoyi.projectmanagement.project.service.IProjectInfoService; import java.util.List; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.validation.annotation.Validated; import org.springframework.web.bind.annotation.*;
/** 项目台账控制器。 */ @RestController @RequestMapping("/projectManagement/project") public class ProjectInfoController extends BaseController { private final IProjectInfoService service; public ProjectInfoController(IProjectInfoService s){service=s;} @PreAuthorize("@ss.hasPermi('projectManagement:project:list')") @GetMapping("/list") public TableDataInfo list(ProjectInfo p){startPage();List<ProjectInfo> list=service.selectProjectInfoList(p);return getDataTable(list);} @PreAuthorize("@ss.hasPermi('projectManagement:project:query')") @GetMapping("/{id}") public AjaxResult get(@PathVariable Long id){return success(service.selectProjectInfoById(id));} @PreAuthorize("@ss.hasPermi('projectManagement:project:add')") @Log(title="项目申请",businessType=BusinessType.INSERT) @PostMapping public AjaxResult add(@Validated @RequestBody ProjectInfo p){if(!service.checkProjectCodeUnique(p))return error("项目编码已存在");p.setCreateBy(getUsername());p.setApplicantDeptId(getDeptId());int rows=service.insertProjectInfo(p);return rows>0?success(p):error();} @PreAuthorize("@ss.hasPermi('projectManagement:project:edit')") @Log(title="项目申请",businessType=BusinessType.UPDATE) @PutMapping public AjaxResult edit(@Validated @RequestBody ProjectInfo p){if(!service.checkProjectCodeUnique(p))return error("项目编码已存在");p.setUpdateBy(getUsername());return toAjax(service.updateProjectInfo(p));} @PreAuthorize("@ss.hasPermi('projectManagement:project:edit')") @Log(title="项目生命周期",businessType=BusinessType.UPDATE) @PostMapping("/{id}/lifecycle") public AjaxResult lifecycle(@PathVariable Long id,@Validated @RequestBody LifecycleActionRequest request){return toAjax(service.applyLifecycleAction(id,request,getUsername()));} @GetMapping("/{id}/preliminary-plans") public AjaxResult plans(@PathVariable Long id){return success(service.preliminaryPlans(id));}@PostMapping("/{id}/preliminary-plans") public AjaxResult addPlan(@PathVariable Long id,@Validated @RequestBody ProjectPreliminaryPlan p){p.setProjectId(id);return toAjax(service.addPreliminaryPlan(p,getUsername()));}@PutMapping("/preliminary-plan") public AjaxResult editPlan(@Validated @RequestBody ProjectPreliminaryPlan p){return toAjax(service.updatePreliminaryPlan(p,getUsername()));}@DeleteMapping("/preliminary-plan/{id}") public AjaxResult deletePlan(@PathVariable Long id){return toAjax(service.deletePreliminaryPlan(id,getUsername()));}@PostMapping("/{id}/initiation/submit") public AjaxResult submit(@PathVariable Long id){return toAjax(service.submitInitiation(id,getUsername()));}@PostMapping("/{id}/initiation/review") public AjaxResult review(@PathVariable Long id,@Validated @RequestBody InitiationReviewRequest r){return toAjax(service.reviewInitiation(id,r,getUsername()));}@GetMapping("/{id}/initiation/approvals") public AjaxResult approvals(@PathVariable Long id){return success(service.approvalHistory(id));}@GetMapping("/{id}/initiation/approvals/{approvalId}") public AjaxResult snapshot(@PathVariable Long id,@PathVariable Long approvalId){return success(service.approvalSnapshot(id,approvalId));}@PreAuthorize("@ss.hasPermi('projectManagement:project:remove')") @Log(title="项目台账",businessType=BusinessType.DELETE) @DeleteMapping("/{ids}") public AjaxResult remove(@PathVariable Long[] ids){return toAjax(service.deleteProjectInfoByIds(ids));}}
